function clipPoly(poly, axis, sign, limit) {
  const out = [];
  const n = poly.length;
  for (let i = 0; i < n; i++) {
    const Aq = poly[i], Bq = poly[(i + 1) % n];
    const da = sign * Aq.getComponent(axis) - limit;
    const db = sign * Bq.getComponent(axis) - limit;
    if (da <= 0) out.push(Aq.clone());
    if ((da < 0 && db > 0) || (da > 0 && db < 0)) {
      const t = da / (da - db);
      out.push(Aq.clone().lerp(Bq, t));
    }
  }
  return out;
}

function planePolygon(n, dist) {
  let u = Math.abs(n.x) < 0.9 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
  u = new THREE.Vector3().crossVectors(n, u).normalize();
  const v = new THREE.Vector3().crossVectors(n, u).normalize();
  const c = n.clone().multiplyScalar(dist);
  const S = 6;
  let poly = [
    c.clone().addScaledVector(u, -S).addScaledVector(v, -S),
    c.clone().addScaledVector(u, S).addScaledVector(v, -S),
    c.clone().addScaledVector(u, S).addScaledVector(v, S),
    c.clone().addScaledVector(u, -S).addScaledVector(v, S)
  ];
  for (let ax = 0; ax < 3; ax++) {
    poly = clipPoly(poly, ax, 1, CLIP_L);
    if (poly.length < 3) return null;
    poly = clipPoly(poly, ax, -1, CLIP_L);
    if (poly.length < 3) return null;
  }
  return poly;
}

