function polyToGeometry(poly, twoTone) {
  const pos = [], col = [];
  let ymin = Infinity, ymax = -Infinity;
  for (const p of poly) { ymin = Math.min(ymin, p.y); ymax = Math.max(ymax, p.y); }
  const span = Math.max(1e-6, ymax - ymin);
  const c = new THREE.Color();
  const push = (p) => {
    pos.push(p.x, p.y, p.z);
    const t = twoTone ? Math.pow((p.y - ymin) / span, 0.9) : 0.5;
    c.copy(DEEP).lerp(PALE, t);
    const a = twoTone ? (0.65 + (0.35 - 0.65) * t) : 0.15;
    col.push(c.r, c.g, c.b, a);
  };
  for (let i = 1; i < poly.length - 1; i++) { push(poly[0]); push(poly[i]); push(poly[i + 1]); }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 4));
  g.computeVertexNormals();
