// @FIGURE_CODE_BEGIN
/* ── Element spec (one line per element) ───────────────────────────────────
   atom (27× per panel) → SphereGeometry(0.10,28,20) MeshPhongMaterial
                          #FF4136 specular #ffffff shininess 55, emissive #2a0806
                          lit by a bright ambient + upper-left white key → vivid red
   atom rim (27×)       → SphereGeometry(0.1055,20,14) MeshBasicMaterial #A0261B BackSide
   in-plane atom        → same red material, group scale 1.30 (r≈0.13), rim → teal #2A7B72
   interior bonds       → LineSegments #1a1a1a (nearest neighbours along x,y,z)
   outer 12 cube edges  → CylinderGeometry(0.015,0.015,2,8) #1a1a1a (heavier)
   cutting plane        → cube∩plane polygon (Sutherland–Hodgman, cube ×1.20),
                          ShaderMaterial: deep #4E9E95 a.62 where |local coord|<1
                          (inside the cube) → pale #CFE7E3 a.34 outside (beyond faces)
   plane border         → LineLoop #2F7C74
   ghost stack          → same polygons, flat teal a.15 + LineLoop outline
   two panels           → panel A (left) and B (right), separated along the
                          screen-right axis of the home view, as in the figure
   labels               → addLabel: Miller caption (15px) + d-formula (13.5px)
                          on a white plate, parked well below each cube
──────────────────────────────────────────────────────────────────────────── */

document.getElementById('btnReset').style.display = '';

/* ── lights: bright ambient so spheres never read maroon ─────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.58));
const keyLight = new THREE.DirectionalLight(0xffffff, 0.92);
keyLight.position.set(-1.2, 3.2, 3.4);          // upper-LEFT front → white dot upper-left
scene.add(keyLight);
const fillLight = new THREE.DirectionalLight(0xffffff, 0.30);
fillLight.position.set(2.6, -1.4, -2.2);
scene.add(fillLight);

/* ── shared geometry / materials ─────────────────────────────────────────── */
const COORDS = [-1, 0, 1];
const sphereGeo = new THREE.SphereGeometry(0.10, 28, 20);
const rimGeo = new THREE.SphereGeometry(0.1055, 20, 14);
const matAtom = new THREE.MeshPhongMaterial({
  color: 0xFF4136, specular: 0xffffff, shininess: 55, emissive: 0x2a0806
});
const matRim = new THREE.MeshBasicMaterial({ color: 0xA0261B, side: THREE.BackSide });
const matRimIn = new THREE.MeshBasicMaterial({ color: 0x2A7B72, side: THREE.BackSide });

const bondPts = [];
for (let ax = 0; ax < 3; ax++) {
  for (const p of COORDS) for (const q of COORDS) {
    if (Math.abs(p) === 1 && Math.abs(q) === 1) continue;   // outer edges are cylinders
    for (let k = 0; k < 2; k++) {
      const a = [0, 0, 0], b = [0, 0, 0];
      const o1 = (ax + 1) % 3, o2 = (ax + 2) % 3;
      a[o1] = p; b[o1] = p; a[o2] = q; b[o2] = q;
      a[ax] = COORDS[k]; b[ax] = COORDS[k + 1];
      bondPts.push(new THREE.Vector3(a[0], a[1], a[2]), new THREE.Vector3(b[0], b[1], b[2]));
    }
  }
}
const bondGeo = new THREE.BufferGeometry().setFromPoints(bondPts);
const bondMat = new THREE.LineBasicMaterial({ color: 0x1a1a1a });
const edgeGeo = new THREE.CylinderGeometry(0.015, 0.015, 2, 8);
const edgeMat = new THREE.MeshBasicMaterial({ color: 0x1a1a1a });

/* ── plane families ──────────────────────────────────────────────────────── */
const FAMILIES = {
  '100': { hkl: [1, 0, 0], label: '(100)', name: 'face-parallel', dText: 'd = a = 1.000 a', d: 1.0 },
  '110': { hkl: [1, 1, 0], label: '(110)', name: 'diagonal', dText: 'd = a/&radic;2 = 0.707 a', d: Math.SQRT1_2 },
  '111': { hkl: [1, 1, 1], label: '(111)', name: 'body-diagonal', dText: 'd = a/&radic;3 = 0.577 a', d: 1 / Math.sqrt(3) }
};
for (const k in FAMILIES) FAMILIES[k].n = new THREE.Vector3(...FAMILIES[k].hkl).normalize();
const CLIP_L = 1.20;   // oversized cube so a pale rim pokes past the faces

function clipPoly(poly, axis, sign, limit) {
  const out = [];
  const n = poly.length;
  for (let i = 0; i < n; i++) {
    const A = poly[i], B = poly[(i + 1) % n];
    const da = sign * A.getComponent(axis) - limit;
    const db = sign * B.getComponent(axis) - limit;
    if (da <= 0) out.push(A.clone());
    if ((da < 0 && db > 0) || (da > 0 && db < 0)) out.push(A.clone().lerp(B, da / (da - db)));
  }
  return out;
}

function planePolygon(n, dist) {
  let u = Math.abs(n.x) < 0.9 ? new THREE.Vector3(1, 0, 0) : new THREE.Vector3(0, 1, 0);
  u = new THREE.Vector3().crossVectors(n, u).normalize();
  const v = new THREE.Vector3().crossVectors(n, u).normalize();
  const c = n.clone().multiplyScalar(dist);
  const S = 6;
  let poly = [
    c.clone().addScaledVector(u, -S).addScaledVector(v, -S),
    c.clone().addScaledVector(u, S).addScaledVector(v, -S),
    c.clone().addScaledVector(u, S).addScaledVector(v, S),
    c.clone().addScaledVector(u, -S).addScaledVector(v, S)
  ];
  for (let ax = 0; ax < 3; ax++) {
    poly = clipPoly(poly, ax, 1, CLIP_L);
    if (poly.length < 3) return null;
    poly = clipPoly(poly, ax, -1, CLIP_L);
    if (poly.length < 3) return null;
  }
  return poly;
}

function polyToGeometry(poly) {
  const pos = [];
  for (let i = 1; i < poly.length - 1; i++) {
    pos.push(poly[0].x, poly[0].y, poly[0].z,
      poly[i].x, poly[i].y, poly[i].z,
      poly[i + 1].x, poly[i + 1].y, poly[i + 1].z);
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.computeVertexNormals();
  g.computeBoundingSphere();
  return g;
}

/* deep teal INSIDE the cube, pale teal where the sheet emerges past the faces */
const planeMat = new THREE.ShaderMaterial({
  transparent: true, side: THREE.DoubleSide, depthWrite: false,
  uniforms: {
    deep: { value: new THREE.Color(0x4E9E95) },
    pale: { value: new THREE.Color(0xCFE7E3) },
    aDeep: { value: 0.62 }, aPale: { value: 0.34 }
  },
  vertexShader: `
    varying vec3 vP;
    void main(){
      vP = position;                                  // cube-local: cube is |c| <= 1
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }`,
  fragmentShader: `
    uniform float aDeep, aPale;
    uniform vec3 deep, pale;
    varying vec3 vP;
    void main(){
      float s = max(max(abs(vP.x), abs(vP.y)), abs(vP.z));
      float t = smoothstep(1.005, 1.045, s);          // 0 inside the cube, 1 beyond it
      gl_FragColor = vec4(mix(deep, pale, t), mix(aDeep, aPale, t));
    }`
});
const planeEdgeMat = new THREE.LineBasicMaterial({ color: 0x2F7C74, transparent: true, opacity: 0.85 });
const PLATE = 'rgba(255,255,255,0.93)';

/* ── panel factory ───────────────────────────────────────────────────────── */
function makePanel(name) {
  const g = new THREE.Group();

  const ag = new THREE.Group();
  g.add(ag);
  const atoms = [];
  for (const x of COORDS) for (const y of COORDS) for (const z of COORDS) {
    const a = new THREE.Group();
    a.position.set(x, y, z);
    const rim = new THREE.Mesh(rimGeo, matRim);
    a.add(rim, new THREE.Mesh(sphereGeo, matAtom));
    ag.add(a);
    atoms.push({ group: a, rim, pos: new THREE.Vector3(x, y, z) });
  }
  registerInteractive(ag, {
    title: 'Lattice atoms',
    tooltip: '3×3×3 simple-cubic lattice, a = 1',
    body: 'Twenty-seven identical atoms on a simple-cubic lattice of constant a. All atoms are the same species and the same red; the ones that actually lie in the teal sheet are drawn slightly larger with a teal rim so you can count them.'
  });

  g.add(new THREE.LineSegments(bondGeo, bondMat));
  for (let ax = 0; ax < 3; ax++) {
    for (const p of [-1, 1]) for (const q of [-1, 1]) {
      const m = new THREE.Mesh(edgeGeo, edgeMat);
      const o1 = (ax + 1) % 3, o2 = (ax + 2) % 3;
      const pos = [0, 0, 0];
      pos[o1] = p; pos[o2] = q;
      m.position.set(pos[0], pos[1], pos[2]);
      if (ax === 0) m.rotation.z = Math.PI / 2;
      if (ax === 2) m.rotation.x = Math.PI / 2;
      g.add(m);
    }
  }

  const pm = new THREE.Mesh(new THREE.BufferGeometry(), planeMat);
  pm.renderOrder = 4;
  g.add(pm);
  registerInteractive(pm, {
    title: 'Atomic plane',
    tooltip: 'Click: what this teal sheet means',
    body: 'This teal sheet is one member of a family of parallel atomic planes, spaced by d = a/√(h²+k²+l²). X-rays reflect from every plane of the family and interfere constructively when 2·d·sinθ = nλ (Bragg\'s law), so each family — (100), (110), (111) … — diffracts at its own angle.'
  });

  const pe = new THREE.LineLoop(new THREE.BufferGeometry(), planeEdgeMat);
  pe.renderOrder = 5;
  g.add(pe);

  const gh = new THREE.Group();
  gh.renderOrder = 3;
  g.add(gh);

  const P = {
    name, group: g, atoms, planeMesh: pm, planeEdge: pe, ghosts: gh,
    fam: '100', idx: 0, stack: false, curM: 0, tweening: false, count: 0
  };
  P.cap = addLabel('', new THREE.Vector3(), { fontSize: '15px', color: '#111', bold: true, offset: [0, 32], background: PLATE });
  P.dlab = addLabel('', new THREE.Vector3(), { fontSize: '13.5px', color: '#333', offset: [0, 58], background: PLATE });
  return P;
}

const panelA = makePanel('A');
const panelB = makePanel('B');
scene.add(panelA.group);
scene.add(panelB.group);

/* ── per-panel rebuilds ──────────────────────────────────────────────────── */
function rebuildPlane(P) {
  const f = FAMILIES[P.fam];
  const poly = planePolygon(f.n, P.curM * f.d);
  const oldG = P.planeMesh.geometry, oldE = P.planeEdge.geometry;
  if (poly) {
    P.planeMesh.geometry = polyToGeometry(poly);
    P.planeEdge.geometry = new THREE.BufferGeometry().setFromPoints(poly);
  } else {
    P.planeMesh.geometry = new THREE.BufferGeometry();
    P.planeEdge.geometry = new THREE.BufferGeometry();
  }
  oldG.dispose(); oldE.dispose();
  P.planeMesh.visible = P.planeEdge.visible = !!poly;
}

function rebuildGhosts(P) {
  while (P.ghosts.children.length) {
    const o = P.ghosts.children.pop();
    o.geometry.dispose();
    if (o.material && o.material !== planeMat) o.material.dispose();
  }
  if (!P.stack) return;
  const f = FAMILIES[P.fam];
  for (let m = -1; m <= 1; m++) {
    if (m === P.idx) continue;
    const poly = planePolygon(f.n, m * f.d);
    if (!poly) continue;
    const mesh = new THREE.Mesh(polyToGeometry(poly), new THREE.MeshBasicMaterial({
      color: 0x4E9E95, transparent: true, opacity: 0.15,
      side: THREE.DoubleSide, depthWrite: false
    }));
    mesh.renderOrder = 3;
    P.ghosts.add(mesh);
    const loop = new THREE.LineLoop(
      new THREE.BufferGeometry().setFromPoints(poly),
      new THREE.LineBasicMaterial({ color: 0x4E9E95, transparent: true, opacity: 0.65 })
    );
    loop.renderOrder = 3;
    P.ghosts.add(loop);
  }
}

function updateHighlights(P) {
  const f = FAMILIES[P.fam];
  let count = 0;
  for (const a of P.atoms) {
    const inPlane = Math.abs(a.pos.dot(f.n) - P.idx * f.d) < 1e-3;
    a.group.scale.setScalar(inPlane ? 1.30 : 1.0);
    a.rim.material = inPlane ? matRimIn : matRim;
    if (inPlane) count++;
  }
  return count;
}

function startTween(P, to) {
  P.tFrom = P.curM; P.tTo = to; P.tStart = performance.now();
  if (P.tweening) return;
  P.tweening = true;
  const tick = () => {
    if (!P.tweening) return;
    const t = Math.min(1, (performance.now() - P.tStart) / 260);
    const e = t * t * (3 - 2 * t);
    P.curM = P.tFrom + (P.tTo - P.tFrom) * e;
    rebuildPlane(P);
    if (t < 1) requestAnimationFrame(tick);
    else { P.curM = P.tTo; P.tweening = false; rebuildPlane(P); }
  };
  requestAnimationFrame(tick);
}

function refreshPanel(P, anim) {
  if (anim) startTween(P, P.idx);
  else { P.curM = P.idx; P.tweening = false; rebuildPlane(P); }
  rebuildGhosts(P);
  P.count = updateHighlights(P);
  const f = FAMILIES[P.fam];
  P.cap.div.innerHTML = f.label + ' planes &nbsp;&middot;&nbsp; ' + f.name;
  P.dlab.div.innerHTML = 'd = a/&radic;(h&sup2;+k&sup2;+l&sup2;) &nbsp;&rarr;&nbsp; ' + f.dText;
}

/* ── layout of the two panels ────────────────────────────────────────────── */
const HOME_AZ = 27, HOME_EL = 14;
const sepDir = new THREE.Vector3(
  Math.sin(THREE.MathUtils.degToRad(HOME_AZ)), 0, -Math.cos(THREE.MathUtils.degToRad(HOME_AZ))
).normalize();                                   // screen-right at the home view
const PANEL_SEP = 1.45;
let twoPanel = true;

function updateLabelPos(P) {
  P.cap.pos.copy(P.group.position).add(new THREE.Vector3(0, -1.48, 0));
  P.dlab.pos.copy(P.cap.pos);
}

function layoutPanels() {
  if (twoPanel) {
    panelA.group.position.copy(sepDir).multiplyScalar(-PANEL_SEP);
    panelB.group.position.copy(sepDir).multiplyScalar(PANEL_SEP);
    if (!panelB.group.parent) scene.add(panelB.group);
    panelB.cap.div.style.visibility = '';
    panelB.dlab.div.style.visibility = '';
  } else {
    panelA.group.position.set(0, 0, 0);
    if (panelB.group.parent) scene.remove(panelB.group);
    panelB.cap.div.style.visibility = 'hidden';
    panelB.dlab.div.style.visibility = 'hidden';
  }
  updateLabelPos(panelA);
  updateLabelPos(panelB);
}

/* ── state + UI ──────────────────────────────────────────────────────────── */
let activeName = 'A';
const active = () => (activeName === 'A' ? panelA : panelB);

panelA.fam = '100'; panelA.idx = 0; panelA.stack = false;
panelB.fam = '110'; panelB.idx = 0; panelB.stack = false;
refreshPanel(panelA, false);
refreshPanel(panelB, false);
layoutPanels();

/* ── camera: mild perspective, shallow axonometric pose ──────────────────── */
function fitCamera() {
  setCameraView({
    projection: 'perspective',
    azimuthDeg: HOME_AZ, elevationDeg: HOME_EL, rollDeg: 0,
    heightFraction: twoPanel ? 0.76 : 0.68
  });
}
fitCamera();
camera.fov = 28;
camera.updateProjectionMatrix();
fitCamera();
controls.minDistance = 3.0;
controls.maxDistance = 32;
controls.target.set(0, 0, 0);
controls.update();

/* ── control wiring ──────────────────────────────────────────────────────── */
const famBtns = {
  '100': document.getElementById('fam100'),
  '110': document.getElementById('fam110'),
  '111': document.getElementById('fam111')
};
const idxSlider = document.getElementById('planeIdx');
const idxVal = document.getElementById('idxVal');
const stackCb = document.getElementById('showStack');
const twoCb = document.getElementById('twoPanel');
const pickA = document.getElementById('pickA');
const pickB = document.getElementById('pickB');
const panelPick = document.getElementById('panelPick');
const readout = document.getElementById('readout');

function syncUI() {
  const P = active();
  for (const k in famBtns) famBtns[k].classList.toggle('active', k === P.fam);
  idxSlider.value = String(P.idx);
  idxVal.textContent = P.idx;
  stackCb.checked = P.stack;
  twoCb.checked = twoPanel;
  panelPick.style.display = twoPanel ? '' : 'none';
  pickA.classList.toggle('active', activeName === 'A');
  pickB.classList.toggle('active', activeName === 'B');
  panelA.cap.div.style.color = (!twoPanel || activeName === 'A') ? '#111' : '#8a8a8a';
  panelB.cap.div.style.color = (activeName === 'B') ? '#111' : '#8a8a8a';
  const f = FAMILIES[P.fam];
  readout.innerHTML =
    '<b>' + (twoPanel ? (activeName === 'A' ? 'Left cube' : 'Right cube') + ' &middot; ' : '') +
    f.label + '</b>, plane m = ' + P.idx + '<br>' + f.dText +
    '<br>atoms lying in this plane: <b>' + P.count + '</b>';
}

for (const k in famBtns) famBtns[k].addEventListener('click', () => {
  stopPlay();
  const P = active();
  P.fam = k;
  refreshPanel(P, false);
  syncUI();
});

idxSlider.addEventListener('input', () => {
  stopPlay();
  const P = active();
  P.idx = parseInt(idxSlider.value, 10);
  refreshPanel(P, true);
  syncUI();
});

stackCb.addEventListener('change', () => {
  stopPlay();
  const P = active();
  P.stack = stackCb.checked;
  refreshPanel(P, false);
  syncUI();
});

twoCb.addEventListener('change', () => {
  stopPlay();
  twoPanel = twoCb.checked;
  if (!twoPanel) activeName = 'A';
  layoutPanels();
  fitCamera();
  syncUI();
});

pickA.addEventListener('click', () => { stopPlay(); activeName = 'A'; syncUI(); });
pickB.addEventListener('click', () => { stopPlay(); activeName = 'B'; syncUI(); });

/* ── guided tour ─────────────────────────────────────────────────────────── */
const STEPS = [
  {
    title: 'The textbook figure: one crystal, two cuts',
    text: 'Two identical 3×3×3 cubic lattices. The left cube carries a sheet parallel to a cube face; the right cube carries a diagonal sheet. Only the orientation of the teal plane differs.',
    two: true, act: 'A', A: { fam: '100', idx: 0, stack: false }, B: { fam: '110', idx: 0, stack: false }
  },
  {
    title: 'Left panel: planes parallel to a cube face',
    text: 'The teal sheet lies parallel to one pair of cube faces and passes through the central sheet of nine atoms. This is the (100) family, spacing d = a.',
    two: true, act: 'A', A: { fam: '100', idx: 0, stack: false }, B: { fam: '110', idx: 0, stack: false }
  },
  {
    title: 'Step to the neighbouring plane',
    text: 'Sliding to the next plane translates the sheet by one lattice constant and lights up the front layer of atoms instead — successive planes of the same family are separated by d.',
    two: true, act: 'A', A: { fam: '100', idx: 1, stack: false }, B: { fam: '110', idx: 0, stack: false }
  },
  {
    title: 'The whole (100) stack',
    text: 'Showing all three planes at once reveals that every atom in the crystal belongs to one plane of this evenly spaced family.',
    two: true, act: 'A', A: { fam: '100', idx: 0, stack: true }, B: { fam: '110', idx: 0, stack: false }
  },
  {
    title: 'Right panel: diagonal (110) planes',
    text: 'Now the same lattice is cut diagonally from the lower left toward the upper right. A different set of spheres lies in the plane, and the spacing tightens to d = a/\u221A2.',
    two: true, act: 'B', A: { fam: '100', idx: 0, stack: false }, B: { fam: '110', idx: 0, stack: false }
  },
  {
    title: 'A steeper family still',
    text: 'The (111) planes slice across three corners; their spacing d = a/\u221A3 is smaller again, so they diffract X-rays at different angles than the (100) or (110) planes.',
    two: true, act: 'B', A: { fam: '100', idx: 0, stack: false }, B: { fam: '111', idx: 0, stack: true }
  }
];
let stepI = 0, playTimer = null;

function applyState(P, st, allowAnim) {
  const sameFam = (P.fam === st.fam);
  P.fam = st.fam; P.idx = st.idx; P.stack = st.stack;
  refreshPanel(P, allowAnim && sameFam);
}

function goToStep(i) {
  stepI = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepI];
  const layoutChanged = (twoPanel !== s.two);
  twoPanel = s.two;
  activeName = s.act;
  applyState(panelA, s.A, true);
  applyState(panelB, s.B, true);
  if (layoutChanged) { layoutPanels(); fitCamera(); }
  syncUI();
  document.getElementById('stepTitle').textContent = (stepI + 1) + '. ' + s.title;
  document.getElementById('stepText').textContent = s.text;
}
function stopPlay() {
  if (playTimer) {
    clearInterval(playTimer); playTimer = null;
    document.getElementById('playSteps').textContent = '\u25B6 Play';
  }
}
document.getElementById('nextStep').addEventListener('click', () => { stopPlay(); goToStep(stepI + 1); });
document.getElementById('prevStep').addEventListener('click', () => { stopPlay(); goToStep(stepI - 1); });
document.getElementById('playSteps').addEventListener('click', () => {
  if (playTimer) { stopPlay(); return; }
  document.getElementById('playSteps').textContent = '\u23F8 Pause';
  goToStep(stepI + 1);
  playTimer = setInterval(() => goToStep(stepI + 1), 4400);
});

goToStep(0);
